INSERT INTO `cell_types` VALUES ('CELL_0000','Hematopoietic stem cell','Multipotent stem cell in bone marrow that gives rise to all blood cell lineages through self-renewal and differentiation.'),('CELL_0001','Melanocyte','Pigment-producing cell not typically present in blood; included as a non-hematopoietic reference population.'),('CELL_0002','Immune cells','Circulating and tissue-associated hematopoietic cells mediating innate and adaptive immune responses.'),('CELL_0003','Axl+ CD123+ Plasmacytoid dendritic cell (CD123+ Axl+DC)','Circulating plasmacytoid dendritic cell subset with intermediate activation features.'),('CELL_0004','B cell','Circulating adaptive lymphocyte responsible for humoral immune responses and antibody production.'),('CELL_0005','Plasmacytoid dendritic cell(pDC)','Rare circulating dendritic cell specialized in antiviral immune responses.'),('CELL_0006','Conventional dendritic cell 1(cDC1)','Blood and tissue dendritic cell subset specialized in antigen cross-presentation.'),('CELL_0007','Eosinophil','Circulating granulocyte involved in antiparasitic and allergic inflammatory responses.'),('CELL_0008','M1 macrophage','Pro-inflammatory macrophage derived from blood monocytes in inflammatory contexts.'),('CELL_0009','T cell','Circulating adaptive lymphocyte mediating cellular immune responses.'),('CELL_0010','Tissue resident memory T(TRM) cell','Memory T cell primarily residing in tissues, derived from circulating T cells.'),('CELL_0011','Mast cell','Tissue-resident hematopoietic cell involved in allergic and inflammatory responses.'),('CELL_0012','Progenitor cell','Hematopoietic precursor with limited self-renewal capacity committed to specific blood lineages.'),('CELL_0013','Conventional dendritic cell 2-A (cDC2-A)','Circulating dendritic cell subset involved in helper T cell priming.'),('CELL_0014','Conventional dendritic cell 2-B (cDC2-B)','Functional subset of circulating cDC2 associated with inflammatory modulation.'),('CELL_0015','Cancerous myeloid derived suppressor cell (MDSC)','Pathological immature myeloid cell in blood with immunosuppressive activity in cancer.'),('CELL_0016','Neutrophil','Most abundant circulating granulocyte involved in acute inflammatory and antibacterial responses.'),('CELL_0017','Axl+ CD11c+ Plasmacytoid dendritic cell (CD11c+ Axl+DC)','Circulating pDC-related subset with intermediate dendritic cell features.'),('CELL_0018','CD16+ dendritic cell (CD16+ DC)','Minor circulating dendritic cell subset with pro-inflammatory properties.'),('CELL_0019','Cancer stem cell','Tumor-derived stem-like cell that may circulate in blood in advanced malignancy.'),('CELL_0020','Leukemic stem cell','Malignant hematopoietic stem cell driving leukemia initiation and persistence in bone marrow and blood.'),('CELL_0021','Regulatory T(Treg) cell','Circulating CD4+ T cell subset maintaining immune tolerance and suppressing immune activation.'),('CELL_0022','Platelet','Anucleate blood component derived from megakaryocytes, essential for hemostasis.'),('CELL_0023','Plasma cell','Antibody-secreting B cell that may circulate transiently or reside in bone marrow.'),('CELL_0024','Monocyte','Circulating myeloid precursor that differentiates into macrophages or dendritic cells in tissues.'),('CELL_0025','Natural killer cell','Circulating innate lymphocyte with cytotoxic activity against infected or transformed cells.'),('CELL_0026','M2 macrophage','Alternatively activated macrophage derived from monocytes, associated with tissue repair and tumor support.'),('CELL_0027','Macrophage','Differentiated monocyte-derived phagocytic cell primarily residing in tissues.'),('CELL_0028','Innate lymphoid cell','Rare circulating or tissue-resident innate lymphocyte contributing to early immune responses.'),('CELL_0029','Red blood cell (erythrocyte)','Anucleate circulating cell specialized in oxygen and carbon dioxide transport.'),('CELL_0030','Cancerous CD8+ T cell','Malignant or tumor-associated cytotoxic T cell detected in hematologic or circulating contexts.'),('CELL_0031','Memory B cell','Long-lived circulating B cell enabling rapid antibody responses upon antigen re-exposure.'),('CELL_0032','CD4+ T cell','Circulating helper T lymphocyte coordinating adaptive immune responses.'),('CELL_0033','CD8 T cell','Circulating cytotoxic T lymphocyte specialized in elimination of infected or malignant cells.'),('CELL_0034','Megakaryocyte','Bone marrow hematopoietic cell responsible for platelet production.'),('CELL_0035','Leukocyte','General term for nucleated blood-derived immune cells.'),('CELL_0036','Lymphocyte','Circulating leukocyte including T, B, and NK cells, central to adaptive and innate immunity.'),('CELL_0037','Circulating tumour cell (CTC)','Tumor-derived cell detected in peripheral blood following detachment from a primary or metastatic site.'),('CELL_0038','Effector T(Teff) cell','Activated circulating T cell with immediate immune effector function.'),('CELL_0039','Cancerous mesenchymal stem cell','Mesenchymal-like malignant cell potentially detected in circulation or tumor-associated blood samples.'),('CELL_0040','Cholangiocyte','Bile duct epithelial cell not normally present in blood; may appear in pathological circulating contexts.'),('CELL_0041','Dendritic cell','Circulating or tissue-migratory antigen-presenting cell linking innate and adaptive immunity.'),('CELL_0042','T helper(Th) cell','Functional subset of circulating CD4+ T cells orchestrating immune responses.'),('CELL_0043','Cancerous CD4+ T cell','Malignant or tumor-associated helper T cell identified in hematologic or circulating samples.'),('CELL_0044','Epithelial cell','Non-hematopoietic structural cell not typically present in blood except in pathological conditions.'),('CELL_0045','Cancerous epithelial stem cell','Tumor-derived epithelial stem-like cell that may be detected in circulation.'),('CELL_0046','T helper 17(Th17) cell','Circulating CD4+ T cell subset associated with inflammatory immune responses.'),('CELL_0047','Cancerous M2 macrophage','Tumor-associated M2-like macrophage detected in hematologic or tumor-derived samples.'),('CELL_0048','Stem cell','Undifferentiated cell with self-renewal capacity; in blood context typically refers to hematopoietic stem cells.'),('CELL_0049','Cancer cell','Malignant cell that may be detected in blood in hematologic cancers or advanced solid tumors.'),('CELL_0050','Cancerous M1 macrophage','Tumor-associated M1-like macrophage with pro-inflammatory characteristics.'),('CELL_0051','Erythroid-like and erythroid precursor cells','Developing erythroid lineage cells typically found in bone marrow and occasionally in peripheral blood under stress conditions.'),('CELL_0052','Platelets','Circulating anucleate fragments derived from megakaryocytes mediating hemostasis and vascular repair.');
/*!40000 ALTER TABLE `cell_types` ENABLE KEYS */;
